mapper.select:
SELECT SYST_ID, ROLE_NO, ROLE_NM, ROLE_DS, PUSE_YN FROM S_EIAM_TIS.AA_ROLE
AND SYST_ID = #{systId}
AND PUSE_YN = #{puseYn}
AND ROLE_NM LIKE '%' || #{keyword} || '%'
ORDER BY ROLE_NM ASC

mapper.delete:
